"""Explain DMA ownership, barrier aliases and SMP versus device ordering."""
import json
from rewrite_c_beginner import rewrite, ROOT
ROWS={'os1633': ('공동 작업 카드에 내용을 다 쓴 뒤 이제 네 차례라는 표시를 붙인다고 생각해 보세요. 표시만 먼저 보이면 상대가 덜 쓴 내용을 읽을 수 있어요.', 'DMA 공유 데이터의 순서와 장치 제어 주소 접근을 구별합니다.', '공유 메모리에는 data와 status를, 별도 칸에는 doorbell을 그리세요. data 기록 → dma_wmb → 장치 차례 표시 → writel로 알림 순서를 적으세요.', ['DMA는 장치가 메모리와 데이터를 주고받을 수 있게 하는 기술이에요. CPU가 모든 바이트를 하나씩 직접 옮기는 방식과 달라요. 여기서는 CPU와 장치가 함께 보는 consistent DMA 메모리의 예시를 배워요. 이런 메모리에서도 접근 순서는 따로 지켜야 해요.', 'descriptor는 장치 작업에 필요한 정보를 담은 카드 같은 구조예요. 문서 예시의 data는 내용이고 status는 지금 CPU와 장치 중 누구 차례인지 알리는 표시예요. ownership은 이처럼 누가 사용할 차례인지를 나타내는 약속이에요.', 'CPU가 status에서 자기 차례임을 확인하면 dma_rmb를 거친 뒤 data를 읽어요. 읽기 장벽을 통해 차례 표시의 관찰과 뒤의 내용 읽기를 연결해요. 장치가 내용을 준비하기 전에 CPU가 먼저 사용하는 상황을 막는 순서 규칙의 일부예요.', 'CPU가 새 내용을 쓸 때는 data 기록 → dma_wmb → 장치 차례라는 status 기록 순서예요. 예를 들어 data를 7에서 9로 고쳤는데 장치가 차례 표시만 먼저 보고 옛값 7을 읽으면 잘못된 작업이 될 수 있어요. dma_wmb는 내용 쓰기가 차례 공개보다 앞서도록 순서를 보강해요.', 'dma_mb는 이 읽기·쓰기 양쪽의 순서 의미를 포함해요. 공통 헤더는 CPU별 __dma_*가 있으면 검사 도구 알림 뒤 그것을 호출하고, 별도 정의가 없으면 mb·rmb·wmb 쪽으로 연결해요. 이름만으로 모든 장치의 설정까지 완료되는 것은 아니에요.', 'MMIO는 장치의 제어 레지스터를 주소로 접근하는 방식이에요. 예시의 doorbell은 새 작업을 알리는 초인종 같은 장치 제어 위치이며 공유 카드의 data와 달라요. dma_* 장벽은 MMIO 접근 순서를 보장하는 도구가 아니에요. 문서는 doorbell 알림에 writel을 쓰며, 이런 I/O 접근 함수의 규칙도 별도로 지켜야 해요.'], [('dma_* 장벽을 쓰면 장치 제어 주소인 MMIO 접근 순서도 모두 보장되나요?', ['네. 장치 제어 주소와 공유 메모리는 항상 같은 규칙이에요', '아니요. MMIO는 I/O 접근 함수의 규칙을 따로 확인해야 해요'], '정답은 두 번째예요. 문서는 dma_*가 MMIO 접근 순서를 보장하지 않는다고 구별해요. 공유 카드의 내용·차례 표시와 장치 초인종을 같은 종류의 칸으로 취급하면 안 돼요.'), ('공유 카드에 내용을 쓴 뒤 장치 차례라고 공개하기 전에 문서 예시는 무엇을 쓰나요?', ['dma_wmb를 써요', 'nop만 한 번 실행해요'], '정답은 첫 번째예요. 내용 기록 → dma_wmb → 장치 차례 표시의 흐름이에요. nop은 이런 메모리 쓰기 순서를 보장하는 장벽이 아니므로 대신 사용할 수 없어요.')]), 'os1634': ('어떤 일을 맡을 전용 창구가 없으면 공통 창구에 연결할 수 있어요. 이름이 달라도 같은 곳으로 이어질 수 있지만, 모든 지점의 처리 속도까지 같다는 뜻은 아니에요.', '장벽 기본 이름의 연결과 적용 조건을 이해합니다.', '별도 정의가 없다고 가정하고 dma_rmb → rmb → mb → barrier를 그리세요. dma_wmb도 같은 방식으로 펼쳐 보세요.', ['alias는 다른 이름으로 연결하는 별칭이에요. 예를 들어 #define rmb() mb()는 rmb()라는 코드를 mb()로 바꾸는 규칙이에요. 실행 중 이름표를 검색하는 동작이 아니라 코드를 번역하기 전의 연결이에요.', '공통 헤더에서 rmb와 wmb가 따로 정의되지 않았다면 둘 다 mb로 연결해요. rmb는 읽기 쪽, wmb는 쓰기 쪽, mb는 더 넓은 메모리 순서 역할의 이름이에요. 더 넓은 기반 동작으로 필요한 좁은 기능을 제공할 수 있어요.', 'DMA 쪽도 별도 정의가 없으면 dma_mb는 mb, dma_rmb는 rmb, dma_wmb는 wmb로 연결해요. 연결표에서 이름을 한 단계씩 바꿔 보면 어디로 이어지는지 알 수 있어요.', 'mb마저 별도 정의가 없을 때의 기본값은 barrier예요. 따라서 모든 기본값을 쓴다는 가정에서는 dma_rmb → rmb → mb → barrier가 돼요. barrier는 컴파일러의 메모리 접근 재배치를 제한하는 장치이며 모든 CPU에서 그것만으로 충분하다는 뜻은 아니에요.', '각 연결 위의 #ifndef는 이미 정의가 있으면 이 기본값을 쓰지 말라는 조건이에요. CPU별로 적합한 별도 장벽을 제공했다면 그 정의를 따라가야 해요. 공통 파일만 보고 실제 마지막 동작을 항상 단정할 수는 없어요.', '이름이 같은 기반으로 이어지는 경우에도 모든 CPU의 속도가 같아지지는 않아요. 실제 명령, CPU의 처리 방식, 함께 실행하는 작업에 따라 비용이 달라져요. 또 이름 연결이 DMA 공유 메모리와 MMIO의 사용 규칙까지 같게 만드는 것도 아니에요.'], [('공통 헤더에서 rmb가 별도로 정의되지 않았다면 어디로 연결되나요?', ['아무 일도 없는 빈 함수로만 연결돼요', 'mb로 연결돼요'], '정답은 두 번째예요. #ifndef rmb 아래에는 rmb()를 mb()로 바꾸는 정의가 있어요. 실제 mb가 무엇인지는 다시 그 정의를 따라가야 하므로 처음부터 빈 함수라고 단정하면 안 돼요.'), ('기본 연결이 같은 이름으로 모이면 모든 CPU에서 속도도 같다고 할 수 있나요?', ['아니요. CPU별 구현과 실행하는 작업을 확인해야 해요', '네. 기본 별칭만 같으면 모든 명령 수와 시간이 같아요'], '정답은 첫 번째예요. 별칭은 코드 연결을 보여 주고, 시간은 실제 구현과 실행 환경에 달려 있어요. 같은 이름으로 연결된다는 사실만으로 성능을 계산할 수 없어요.')]), 'os1635': ('안내 창구 두 곳에서 각각 접수 사실을 기록한 뒤 실제 작업은 한 곳에 맡길 수 있어요. 기록이 두 번이라고 실제 작업도 반드시 두 번인 것은 아니에요.', 'SMP 장벽의 내부 연결과 검사 알림의 중첩을 구별합니다.', 'CONFIG_SMP가 켜지고 __mb만 제공된 경우를 가정하세요. smp_mb → 알림 → __smp_mb → mb → 알림 → __mb를 펼쳐 그리세요.', ['SMP는 여러 CPU가 함께 일하는 구성을 뜻해요. smp_mb는 그런 CPU 사이의 메모리 순서에 쓰는 공개 이름이고, __smp_mb는 여기서 연결할 내부 기반 이름이에요. 앞의 밑줄 두 개가 별도의 장벽 명령을 뜻하는 것은 아니에요.', 'CPU별 __smp_mb가 따로 없으면 공통 헤더는 __smp_mb를 mb로 연결해요. __smp_rmb와 __smp_wmb도 각각 rmb와 wmb로 이어져요. 자기 자신인 smp_mb를 끝없이 다시 부르는 연결이 아니에요.', 'CONFIG_SMP가 켜진 공통 smp_mb는 먼저 kcsan_mb로 검사 도구에 알리고 __smp_mb를 호출해요. KCSAN은 동시에 접근하는 코드의 문제를 찾는 검사 도구이고, 이 알림은 순서 관계를 알려 주는 역할이에요.', '이제 __smp_mb는 없고 CPU별 __mb만 제공됐다고 가정해 보세요. __smp_mb → mb로 이어지고, mb 안에서도 kcsan_mb 뒤 __mb를 호출해요. 따라서 펼친 코드에는 검사 알림 두 번과 __mb 호출 한 번이 나타나요.', '반대로 CPU별 __smp_mb를 직접 제공하면 중간에 mb로 이어지는 기본값을 쓰지 않아요. 어떤 경로인지는 먼저 정의된 이름과 #ifndef 조건을 확인해야 해요. 위의 두 번 알림 예시는 지정한 구성에서의 흐름이에요.', '검사 도구에 알리는 횟수를 CPU 장벽 명령 수로 바꾸어 세면 안 돼요. 알림은 분석을 위한 정보이고 실제 명령은 CPU별 구현에서 정해져요. 종이에 호출 경로를 확인한 것은 실제 KCSAN이나 모든 CPU의 동작을 시험한 결과와도 달라요.'], [('내부 __smp_mb가 따로 정의되지 않았을 때 공통 기본 연결은 무엇인가요?', ['smp_mb 자신을 계속 다시 부르는 것이에요', 'mb로 연결하는 것이에요'], '정답은 두 번째예요. __smp_mb의 기본 정의는 mb()예요. 공개 smp_mb, 내부 __smp_mb, 기반 mb라는 서로 다른 이름을 구별해서 따라가세요.'), ('검사 알림이 두 번 보이면 CPU의 실제 장벽 명령도 반드시 두 개인가요?', ['아니요. 알림과 실제 기반 구현은 따로 확인해야 해요', '네. 알림 횟수는 항상 CPU 장벽 명령 수와 같아요'], '정답은 첫 번째예요. 위 구성은 두 층에서 각각 알리고 마지막에 __mb로 이어져요. 실제 명령 개수는 __mb의 CPU별 구현을 봐야 알 수 있어요.')]), 'os1636': ('일하는 사람이 한 명이어도 자동 기계와 주고받는 순서는 지켜야 해요. 다른 CPU가 없다는 것과 장치까지 없다는 것은 다른 말이에요.', 'SMP·UP의 기본 분기와 장치 순서의 필요성을 구별합니다.', '다른 CPU와 협력 / 장치와 협력을 두 칸에 적으세요. UP에서 첫째의 기본 smp 장벽이 compiler barrier가 되어도 둘째의 순서 규칙은 남는다고 표시하세요.', ['SMP는 여러 CPU를 함께 사용하는 구성이고 UP는 CPU 하나를 사용하는 구성이에요. CONFIG_SMP는 커널을 만들 때 이런 지원을 선택하는 설정이에요. 이 헤더에서는 전처리 조건으로 두 경우의 기본 코드를 나눠요.', 'CONFIG_SMP가 켜지면 기본 smp_mb는 kcsan_mb로 순서를 알리고 __smp_mb를 호출해요. smp_rmb와 smp_wmb도 각각 읽기·쓰기 쪽 알림과 내부 구현으로 이어져요.', 'CONFIG_SMP가 꺼진 쪽에서는 별도 정의가 없는 smp_mb·smp_rmb·smp_wmb를 모두 barrier()에 연결해요. 이것은 컴파일러가 메모리 접근을 함부로 장벽 너머로 옮기지 않도록 하는 컴파일러 장벽이에요.', '이 선택은 smp_*라는 CPU 사이의 순서 도구에 관한 기본값이에요. 컴퓨터의 모든 장벽과 모든 장치 접근을 지워도 된다는 명령이 아니에요. CPU가 하나라도 장치는 별도로 일을 할 수 있어요.', '예를 들어 CPU가 장치에게 읽힐 내용을 쓰고 작업 시작을 알리는 상황을 생각해 보세요. 내용보다 시작 알림을 장치가 먼저 보게 되면 문제가 생길 수 있어요. 다른 CPU가 없더라도 CPU와 장치 사이의 순서가 필요한 이유예요.', '따라서 코드를 사용할 때 누구와 데이터를 주고받는지 먼저 적어 보세요. 다른 CPU인지 DMA 장치인지 MMIO 제어 위치인지에 따라 알맞은 API와 규칙을 골라야 해요. UP라는 이유만으로 장치 접근 함수를 일반 메모리 쓰기로 바꾸거나 필요한 순서를 생략하면 안 돼요.'], [('UP 분기에서 따로 정의되지 않은 smp_mb의 기본값은 무엇인가요?', ['모든 장치의 DMA 내용을 비우는 명령이에요', '컴파일러 장벽인 barrier()예요'], '정답은 두 번째예요. !CONFIG_SMP 쪽 정의가 smp_mb를 barrier로 연결해요. smp_mb의 기본 분기를 장치의 DMA 처리 명령으로 읽으면 안 돼요.'), ('CPU가 하나인 UP이면 장치와 주고받는 순서도 필요 없나요?', ['아니요. CPU와 장치 사이의 순서 규칙은 별도로 필요해요', '네. 장치는 CPU와 완전히 같은 실행 주체예요'], '정답은 첫 번째예요. CPU가 하나여도 장치는 따로 동작할 수 있어요. 내용 준비와 작업 알림의 순서를 지켜야 하는 상황이 남으므로 장치에 맞는 접근 규칙을 따라야 해요.')])}
def run():
    additions={}
    for path in (ROOT/'course/lesson-parts').glob('*.json'):
        for lesson in json.loads(path.read_text(encoding='utf-8')):
            key=lesson['id']
            if key not in ROWS:continue
            practice=dict(lesson.get('practice',{}));practice['expected']=ROWS[key][2]
            additions[key]=dict(concepts=[],reading_support=None,deep_dive=[],goal=ROWS[key][1],experiment={'title':'종이에 따라 해 보기','steps':[ROWS[key][2]]},practice=practice)
    return rewrite(ROWS,'tools/rewrite_os_beginner_404.py',additions)
if __name__=='__main__':print(json.dumps(run(),ensure_ascii=False))
